export const MONUMENTS = JSON.parse("[{\"id\":\"n318501546\",\"kind\":\"memorial\",\"sub\":\"statue\",\"name\":\"М. И. Кутузову\",\"x\":-1415.4,\"z\":-285.4,\"material\":\"bronze\",\"wikidata\":\"Q21843382\",\"wikipedia\":\"ru:Памятники Кутузову и Барклаю-де-Толли (Санкт-Петербург)\"},{\"id\":\"n318501570\",\"kind\":\"memorial\",\"sub\":\"statue\",\"name\":\"М. Б. Барклаю-де-Толли\",\"x\":-1510.5,\"z\":-314.8,\"material\":\"bronze\",\"startDate\":\"1837-06-15\",\"artist\":\"Б. И. Орловский, С. К. Суханов\",\"wikidata\":\"Q21843382\",\"wikipedia\":\"ru:Памятники Кутузову и Барклаю-де-Толли (Санкт-Петербург)\"},{\"id\":\"n477027518\",\"kind\":\"memorial\",\"sub\":\"statue\",\"name\":\"А. С. Пушкину\",\"x\":-1099.1,\"z\":-538.9,\"wikidata\":\"Q9396452\",\"wikipedia\":\"ru:Памятник А. С. Пушкину (Санкт-Петербург, площадь Искусств)\"},{\"id\":\"n6077061649\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Е. А. Мравинскому\",\"x\":-1107.6,\"z\":-432.1,\"subject\":\"Q320609\",\"inscription\":\"Евгений Мравинский творил здесь LVI лет\"},{\"id\":\"n6077061650\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Исполнению Седьмой (Ленинградской) симфонии Д. Д. Шостаковича\",\"x\":-1102.9,\"z\":-452.2,\"subject\":\"Q261140\",\"inscription\":\"Здесь, в Большом зале Ленинградской филармонии, 9 августа 1942 года оркестр Ленинградского радиокомитета под управлением дирижера К. И. Элиасберга исполнил Седьмую (Ленинградскую) симфонию Д. Д. Шостаковича\"},{\"id\":\"n6484436342\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. П. Павловой\",\"x\":-1174.9,\"z\":-477.7,\"subject\":\"Q151874\",\"inscription\":\"Великая русская балерина Анна Павлова жила в этом доме в 1910 году\"},{\"id\":\"n13247901901\",\"kind\":\"artwork\",\"sub\":\"statue\",\"name\":\"Фредди Меркьюри\",\"x\":-1141.3,\"z\":-288.3,\"subject\":\"Q15869\"},{\"id\":\"n4683728162\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"К. А. Глуховскому\",\"x\":-2004.1,\"z\":-289.6,\"subject\":\"Q18071580\",\"inscription\":\"В этом доме с 1963 по 1987 год работал начальник Главзапстроя Герой социалистического труда, лауреат государственных премий в области строительства Корнелий Аркадьевич Глуховской\"},{\"id\":\"n10126606282\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. Н. Косыгину\",\"x\":-1964.3,\"z\":-285,\"subject\":\"Q202770\",\"inscription\":\"С 1930 по 1935 г. в этом здании учился и окончил Текстильный институт Алексей Николаевич Косыгин, видный деятель Коммунистической партии и Советского государства\"},{\"id\":\"n4683728164\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Н. В. Гоголю\",\"x\":-2268.6,\"z\":-285.8,\"subject\":\"Q43718\",\"inscription\":\"В этом доме с 1833 г. по 1836 г. жил Николай Васильевич Гоголь\"},{\"id\":\"n4683728165\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. К. Блюхеру\",\"x\":-2178.6,\"z\":-351,\"subject\":\"Q48129\",\"inscription\":\"В этом доме с 1923 по 1926 год жил выдающийся советский полководец, Маршал Советского Союза Василий Константинович Блюхер\"},{\"id\":\"n4683728166\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Г. С. Улановой\",\"x\":-2191.1,\"z\":-341.9,\"subject\":\"Q28885\",\"inscription\":\"В этом доме с 1926 по 1935 год жила великая русская балерина Галина Сергеевна Уланова\"},{\"id\":\"n4683728167\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"П. И. Чайковскому\",\"x\":-2188.9,\"z\":-343.6,\"subject\":\"Q7315\",\"inscription\":\"Пётр Ильич Чайковский родился 25-го апреля 1840-го года в Вятской губернии на Воткинском заводе. Скончался в этом доме 25-го октября 1893-го года\"},{\"id\":\"n6481181510\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-2166.1,\"z\":-331.4,\"startDate\":\"2018-10-04\",\"inscription\":\"В этом здании с 01.12.1917 по 15.07.1918 располагалось Петроградское столичное управление уголовного розыска\"},{\"id\":\"n7532311480\",\"kind\":\"artwork\",\"name\":\"Лев\",\"x\":-2453,\"z\":-323.2,\"description\":\"Лев у дома Лобанова-Ростовского\"},{\"id\":\"n7532311481\",\"kind\":\"artwork\",\"name\":\"Лев\",\"x\":-2448.4,\"z\":-326.8,\"description\":\"Лев у дома Лобанова-Ростовского\"},{\"id\":\"n9014964903\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-2509.5,\"z\":-319.5,\"subject\":\"Q3162435\"},{\"id\":\"n9927579884\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Общество ремесленного и земледельческого труда\",\"x\":-2867.5,\"z\":-297.2,\"inscription\":\"В этом доме в 1880 году Петербургской еврейской общиной основано Общество ремесленного и земледельческого труда среди евреев в России, внесшее значительный вклад в профессиональное обучение российской молодежи\"},{\"id\":\"n6419451604\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Н. К. Рериху\",\"x\":-3588.5,\"z\":-471.5,\"subject\":\"Q208993\",\"inscription\":\"В этом доме родился и жил с 1874 по 1899 год мыслитель-гуманист, художник Николай Рерих\"},{\"id\":\"n7683216131\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. А. Стеклову\",\"x\":-3649.4,\"z\":-453.2,\"subject\":\"Q559188\",\"inscription\":\"Здесь жил академик Владимир Андреевич Стеклов, 1863–1926, выдающийся математик\"},{\"id\":\"n7683216132\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Б. С. Якоби\",\"x\":-3652.3,\"z\":-451.6,\"subject\":\"Q60579\",\"inscription\":\"Здесь жил академик Борис Семенович Якоби, 1801–1874. Выдающийся физик и электротехник. Изобретатель гальванопластики, электрического телеграфа, электрических моторных лодок, электрических мин.\"},{\"id\":\"n7683216133\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. П. Карпинскому\",\"x\":-3655.2,\"z\":-450,\"subject\":\"Q729563\",\"inscription\":\"Здесь жил с 1899 г. по 1935 г. Президент Академии Наук СССР Александр Петрович Карпинский, знаменитый геолог, «отец русской геологии», 1847–1936\"},{\"id\":\"n7683216134\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"И. Ю. Крачковскому\",\"x\":-3661.2,\"z\":-446.6,\"subject\":\"Q1996028\",\"inscription\":\"В этом доме жил и умер выдающийся советский ученый-востоковед, крупнейший деятель русской арабистики, академик Игнатий Юлианович Крачковский (1883–1951 гг.)\"},{\"id\":\"n7683216135\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"И. И. Мещанинову\",\"x\":-3675.5,\"z\":-438.6,\"subject\":\"Q1342113\",\"inscription\":\"В этом доме с 1941 по 1967 год жил выдающийся советский языковед и археолог, академик Иван Иванович Мещанинов, 1883–1967\"},{\"id\":\"n7683216136\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"М. П. Алексееву\",\"x\":-3681.5,\"z\":-435.3,\"subject\":\"Q4061691\",\"inscription\":\"Здесь с 1966 по 1981 год жил и работал советский ученый-филолог, академик Михаил Павлович Алексеев\"},{\"id\":\"n7683216137\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"М. В. Остроградскому\",\"x\":-3684.2,\"z\":-433.7,\"subject\":\"Q355892\",\"inscription\":\"Здесь жил академик Михаил Васильевич Остроградский, 1801–1861, знаменитый математик. Широко известны его работы по основаниям механики и его формулы в теории кратных интергалов.\"},{\"id\":\"n7685081678\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"П. Л. Чебышёву\",\"x\":-3684.4,\"z\":-434,\"subject\":\"Q206012\",\"inscription\":\"Здесь жил академик Пафнутий Львович Чебышев, 1821–1894, знаменитый математик, основатель русской школы теории чисел, теории вероятностей, теории механизмов и теории функций, сделавший основные открытия в этих науках.\"},{\"id\":\"n7685081679\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. В. Ферсману\",\"x\":-3681.6,\"z\":-435.6,\"subject\":\"Q365645\",\"inscription\":\"Здесь с 1920 г. по 1936 г. жил академик Александр Евгеньевич Ферсман, выдающийся геохимик и минералог.\"},{\"id\":\"n7685081680\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. И. Палладину\",\"x\":-3675.7,\"z\":-439,\"subject\":\"Q899297\",\"inscription\":\"Здесь жил с 1921 года и 3 февраля 1922 года умер академик Владимир Иванович Палладин, выдающийся русский физиолог растений.\"},{\"id\":\"n7685081681\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. П. Васильеву\",\"x\":-3661.5,\"z\":-447,\"subject\":\"Q721077\",\"inscription\":\"Здесь жил академик Василий Павлович Васильев, 1818–1900. Крупнейший русский китаевед.\"},{\"id\":\"n7685081682\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. И. Вернадскому\",\"x\":-3655.5,\"z\":-450.5,\"subject\":\"Q316371\",\"inscription\":\"Здесь жил академик Владимир Иванович Вернадский, 1863–1945. Знаменитый геолог и минералог. Основоположник науки о химии земли.\"},{\"id\":\"n7685081683\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. В. Петрову\",\"x\":-3652.6,\"z\":-452.1,\"subject\":\"Q2721074\",\"inscription\":\"Здесь жил академик Василий Владимирович Петров, 1761–1834. Выдающийся физик и химик, изобретатель электрической дуги.\"},{\"id\":\"n7685081684\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"И. П. Павлову\",\"x\":-3649.7,\"z\":-453.8,\"subject\":\"Q42985\",\"inscription\":\"Здесь жил и умер великий русский физиолог Иван Петрович Павлов, 1849–1936\"},{\"id\":\"n7688151085\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. М. Ляпунову\",\"x\":-3648.7,\"z\":-455.4,\"subject\":\"Q310788\",\"inscription\":\"Здесь жил академик Александр Михайлович Ляпунов, 1857–1918. Знаменитый математик, создатель общей теории устойчивости и теории фигур небесных тел.\"},{\"id\":\"n7688151086\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. А. Борисяку\",\"x\":-3650.4,\"z\":-458.5,\"subject\":\"Q4094072\",\"inscription\":\"Здесь жил академик Алексей Алексеевич Борисяк, 1872–1944. Выдающийся палеонтолог.\"},{\"id\":\"n7688151087\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Я. К. Гроту\",\"x\":-3652.2,\"z\":-461.5,\"subject\":\"Q2995186\",\"inscription\":\"Здесь жил академик Яков Карлович Грот, 1812–1893. Преобразователь русской орфографии и составитель «Словаря русского языка».\"},{\"id\":\"n7688151088\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"С. Ф. Ольденбургу\",\"x\":-3653.9,\"z\":-464.5,\"subject\":\"Q171848\",\"inscription\":\"Здесь жил академик Сергей Федорович Ольденбург, 1863–1934. Выдающийся индолог.\"},{\"id\":\"n7688151089\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. О. Ковалевскому\",\"x\":-3655.6,\"z\":-467.5,\"subject\":\"Q560321\",\"inscription\":\"В этом доме жил с 1892 по 1901 год академик Александр Онуфриевич Ковалевский, выдающийся русский зоолог и эмбриолог.\"},{\"id\":\"n7688151090\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Ф. Ю. Левинсону-Лессингу\",\"x\":-3655.2,\"z\":-467.8,\"subject\":\"Q1396733\",\"inscription\":\"Выдающийся русский петрограф, академик Франц Юльевич Левинсон-Лессинг жил в этом доме с 1929 г. по 1939 г.\"},{\"id\":\"n7688151091\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Ф. И. Успенскому\",\"x\":-3653.5,\"z\":-464.7,\"subject\":\"Q451292\",\"inscription\":\"Здесь жил академик Федор Иванович Успенский, 1845–1928. Знаменитый русский византолог.\"},{\"id\":\"n7688151092\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. С. Орлову\",\"x\":-3651.8,\"z\":-461.7,\"subject\":\"Q4336606\",\"inscription\":\"Здесь жил академик Александр Сергеевич Орлов, 1871–1947. Выдающийся исследователь русской литературы.\"},{\"id\":\"n7688151093\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. С. Фаминцыну\",\"x\":-3650.1,\"z\":-458.6,\"subject\":\"Q2067228\",\"inscription\":\"Здесь жил академик Андрей Сергеевич Фаминцын. 1835–1918. Выдающийся ботаник.\"},{\"id\":\"n7688151094\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. А. Маркову\",\"x\":-3648.4,\"z\":-455.6,\"subject\":\"Q176659\",\"inscription\":\"Здесь жил академик Андрей Андреевич Марков, 1856–1922. Выдающийся математик, широко известный своими работами по теории чисел и теории вероятностей.\"},{\"id\":\"n7688189766\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. И. Шёгрену\",\"x\":-3669.9,\"z\":-493.9,\"subject\":\"Q1394543\",\"inscription\":\"Здесь с 1833 по 1855 год жил российский академик Андреас Иоган Шёгрен, выдающийся исследователь истории, языка и культуры Финляндии и финно-угорских народов\"},{\"id\":\"n7688189768\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Н. Я. Марру\",\"x\":-3661.7,\"z\":-478.1,\"subject\":\"Q116309\",\"inscription\":\"Здесь жил с 1918 г. по 1964 г. академик Николай Яковлевич Марр. Выдающийся археолог и языковед, 1864–1934\"},{\"id\":\"n7688189769\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. М. Алексееву\",\"x\":-3663.3,\"z\":-481.1,\"subject\":\"Q921322\",\"inscription\":\"Здесь жил с 1939 по 1951 год академик Василий Михайлович Алексеев — крупнейший советский исследователь литературы, языка и культуры Китая\"},{\"id\":\"n7688189770\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. С. Бушмину\",\"x\":-3662.8,\"z\":-481.3,\"subject\":\"Q4100687\",\"inscription\":\"В этом доме с 1966 по 1983 год жил и работал крупный советский литературовед, академик Алексей Сергеевич Бушмин\"},{\"id\":\"n7688189771\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"С. А. Зернову\",\"x\":-3661.2,\"z\":-478.4,\"subject\":\"Q4191600\",\"inscription\":\"Здесь жил с 1931 года и скончался выдающийся гидробиолог, академик Сергей Алексеевич Зернов, 1871–1945\"}]");
